{
  "packet_id": "H6-T04-2",
  "claim_id": "C029",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C029.main",
    "value": "Post-release observation should assess change in the proportion of accounts reaching a traceable first publication within the predefined window.",
    "scope": "A proposed, time-bounded publication measure; no direction or magnitude of change is reported.",
    "provenance": {
      "refs": [
        {"source_id": "P015", "role": "SUPPORT"},
        {"source_id": "P016", "role": "SUPPORT"}
      ],
      "support_status": "SUFFICIENT",
      "rationale": "These spans supply the publication proportion, traceability requirement, predefined window and proposed status."
    }
  },
  "signal_basis": {
    "component_id": "C029.signal_basis",
    "value": "Define eligible accounts, a common observation window and outcome-recording checks; observe post-release change in the proportion reaching traceable first publication, checking linkage and capture comparability and separately reporting accounts whose publication opportunity has not occurred.",
    "scope": "Proposed observation within the agreed window, conditional on the stated execution prerequisites; no completed result is asserted.",
    "provenance": {
      "refs": [
        {"source_id": "P009", "role": "SUPPORT"},
        {"source_id": "P011", "role": "SUPPORT"},
        {"source_id": "P015", "role": "SUPPORT"},
        {"source_id": "P016", "role": "SUPPORT"},
        {"source_id": "P025", "role": "SUPPORT"}
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The bundle supplies the measurement procedure, observation, prospective status and recording safeguards."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C029.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "No unresolved empirical relation is needed to license this bounded measurement proposal."
    }
  },
  "rationale": "The operation defines the population, publication outcome and observation window needed to assess the proposed proportion. With the stipulated prerequisites satisfied, that observation licenses this measurement claim. The claim asserts neither an improvement nor a causal effect.",
  "uncertainty": "The direction and magnitude of any change remain unspecified; neither is required by this claim.",
  "anomalies": []
}
